using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using MyDoc.Data;using MyDoc.Models;using MyDoc.Services;
namespace MyDoc.Pages;[Authorize]public sealed class IndexModel(DocSpaceDbContext db,ICurrentUserService users,IDocumentImportService importer,IDocxImportService docx):PageModel{public ApplicationUser?CurrentUser{get;private set;}public List<Document>Owned{get;private set;}=[];public List<Document>Shared{get;private set;}=[];[BindProperty]public IFormFile?ImportFile{get;set;}[BindProperty]public string?ImportTitle{get;set;}public async Task OnGetAsync(CancellationToken ct){CurrentUser=await users.GetCurrentAsync(User);if(CurrentUser is null)return;Owned=await db.Documents.Include(d=>d.Owner).Where(d=>d.OwnerId==CurrentUser.Id).ToListAsync(ct);Shared=await db.Documents.Include(d=>d.Owner).Include(d=>d.Shares).Where(d=>d.OwnerId!=CurrentUser.Id&&d.Shares.Any(s=>s.UserId==CurrentUser.Id)).ToListAsync(ct);}public async Task<IActionResult>OnPostCreateAsync(CancellationToken ct){var u=await users.GetCurrentAsync(User);if(u is null)return Challenge();var d=new Document{OwnerId=u.Id,CreatedAtUtc=DateTime.UtcNow,UpdatedAtUtc=DateTime.UtcNow};db.Documents.Add(d);await db.SaveChangesAsync(ct);return RedirectToPage("/Documents/Edit",new{id=d.Id});}public async Task<IActionResult>OnPostImportAsync(CancellationToken ct){var u=await users.GetCurrentAsync(User);if(u is null)return Challenge();var r=await importer.ConvertAsync(ImportFile,ct);if(!r.Ok){TempData["Error"]=r.Error;return RedirectToPage();}return await Add(u,r.Html,ImportTitle??Path.GetFileNameWithoutExtension(ImportFile!.FileName),ct);}public async Task<IActionResult>OnPostWordAsync(CancellationToken ct){var u=await users.GetCurrentAsync(User);if(u is null)return Challenge();var r=await docx.ConvertAsync(ImportFile,ct);if(!r.Ok){TempData["Error"]=r.Error;return RedirectToPage();}return await Add(u,r.Html,Path.GetFileNameWithoutExtension(ImportFile!.FileName),ct);}async Task<IActionResult>Add(ApplicationUser u,string html,string title,CancellationToken ct){var d=new Document{OwnerId=u.Id,Title=title.Length>200?title[..200]:title,ContentHtml=html,CreatedAtUtc=DateTime.UtcNow,UpdatedAtUtc=DateTime.UtcNow};db.Documents.Add(d);await db.SaveChangesAsync(ct);return RedirectToPage("/Documents/Edit",new{id=d.Id});}public async Task<IActionResult>OnPostDeleteAsync(int id,CancellationToken ct){var u=await users.GetCurrentAsync(User);if(u is null)return Challenge();var d=await db.Documents.FirstOrDefaultAsync(x=>x.Id==id&&x.OwnerId==u.Id,ct);if(d is null)return NotFound();db.Documents.Remove(d);await db.SaveChangesAsync(ct);return RedirectToPage();}}
